    special = next(v for row in grid for v in row
                   if v not in (0, 1, 2, 3, 5, 7, 9))
    # The special color is the one occurring as a small embedded shape;
    # background colors are 0 and the other dominant color.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    special = min(counts, key=counts.get)
    out = [row[:] for row in grid]
    seen = set()
    stack = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] == special]
    while stack:
        r, c = stack.pop()
        for nr, nc in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and (nr,nc) not in seen:
                if grid[nr][nc] == 0:
                    seen.add((nr,nc))
                    out[nr][nc] = special
                    stack.append((nr,nc))
    return out
